   160→    /// Verify the versioned hashes computed by the blob transactions match the versioned hashes computed from the commitments.
   161→    ///
   162→    /// ## Specification
   163→    ///
   164→    /// Equivalent to `is_valid_versioned_hashes` in the spec:
   165→    /// https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.2/specs/deneb/beacon-chain.md#is_valid_versioned_hashes
   166→    pub fn verify_versioned_hashes(&self) -> Result<(), Error> {
